//! Bitmaps of the fonts and logos in `deck/assets/` and of OpenAI's pets,
//! generated by `tools/assets`. Do not edit; rerun
//! `cargo run --manifest-path tools/assets/Cargo.toml` instead.

use crate::draw::{Font, Image, SpriteSheet};

/// Ark Pixel at its 12 px pixel size, pixel for pixel, for body text: ASCII and `…`.
pub(crate) const BODY: Font = Font {
    chars: " !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~…",
    width: 6,
    height: 11,
    baseline: 9,
    data: include_bytes!("../assets/gen/body.bin"),
};

/// DotGothic16 at twice its pixel size, for big numbers.
pub(crate) const NUMERAL: Font = Font {
    chars: "0123456789-",
    width: 16,
    height: 27,
    baseline: 26,
    data: include_bytes!("../assets/gen/numeral.bin"),
};

/// DotGothic16's `%` at its 16 px pixel size, pixel for pixel, after big numbers.
pub(crate) const PERCENT: Font = Font {
    chars: "%",
    width: 8,
    height: 13,
    baseline: 13,
    data: include_bytes!("../assets/gen/percent.bin"),
};

/// DotGothic16's kanji at its 16 px pixel size, pixel for pixel.
pub(crate) const KANJI: Font = Font {
    chars: "稼働待機今",
    width: 16,
    height: 15,
    baseline: 14,
    data: include_bytes!("../assets/gen/kanji.bin"),
};

/// Claude's logo, for Claude Code. Quarter size, for subagents.
pub(crate) const CLAUDE_SMALL: Image = Image {
    width: 8,
    height: 8,
    data: include_bytes!("../assets/gen/claude_small.bin"),
};

/// pi's logo, from the press kit at <https://pi.dev/press-kit>. Quarter size, for subagents.
pub(crate) const PI_SMALL: Image = Image {
    width: 8,
    height: 8,
    data: include_bytes!("../assets/gen/pi_small.bin"),
};

/// OpenAI's logo, for Codex. Quarter size, for subagents.
pub(crate) const OPENAI_SMALL: Image = Image {
    width: 8,
    height: 8,
    data: include_bytes!("../assets/gen/openai_small.bin"),
};

/// OpenAI's pets, downloaded by `tools/assets` and not in
/// git: 8 pets, each with an idle and a busy animation.
pub(crate) const PETS: SpriteSheet = SpriteSheet {
    sprites: 8,
    animations: 2,
    frames: 6,
    width: 36,
    height: 36,
    data: include_bytes!("../assets/gen/pets.bin"),
};
